class Solution:
    def isHappy(self, n: int) -> bool:
        def squareSum(num: int) -> int:
            total = 0
            while num > 0:
                digit = num % 10
                total += digit ** 2
                num //= 10
            return total

        slow = n
        fast = squareSum(squareSum(n))
        while fast != 1:
            slow = squareSum(slow)
            fast = squareSum(squareSum(fast))

            if slow == fast:
                return False

        return True
